use dioxus_native::prelude::*;

/// Generated by `dx build`/`dx serve` from `tailwind.css`, then bundled by dx
/// under a content-hashed name.
const TAILWIND_CSS: Asset = asset!("/assets/tailwind.css");

fn main() {
    init_logging();
    install_crypto_provider();
    warn_if_unbundled();
    dioxus_native::launch(App);
}

/// What is logged when `RUST_LOG` says nothing: our own progress and the audio
/// library's device and echo-canceller lines, warnings from everything else.
///
/// **Not silence.** The old default logged nothing at all, so a call that went
/// wrong on someone else's machine left no evidence to send back -- which is
/// exactly where echo turned up.
///
/// `vello_common` only at `error`: it warns "A path contains NaN" about 1,300
/// times a second on every build so far, which would bury everything else in
/// the file. Present on master too; quietened here rather than fixed.
const DEFAULT_LOG: &str = "warn,vdr=info,moq_audio=info,vello_common=error";

/// How many earlier runs' logs are kept beside the current one.
///
/// One was not enough: someone reporting a call that went wrong usually
/// starts the app again before they get round to sending anything, and a
/// second start (a quick retry, a test instance on the same machine) took the
/// one copy with it. Three covers an afternoon.
const KEPT_LOGS: u32 = 3;

/// Logs to stderr and to `vdr.log` in the app's data folder.
///
/// The file is truncated at each launch, with earlier runs kept beside it as
/// `vdr.1.log` (the last run) up to `vdr.3.log`. An explicit `RUST_LOG` still
/// decides what is written to all of them.
fn init_logging() {
    use tracing_subscriber::prelude::*;

    let filter = || {
        tracing_subscriber::EnvFilter::try_from_default_env()
            .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new(DEFAULT_LOG))
    };
    let file = settings::log_path().and_then(|path| {
        rotate(&path);
        std::fs::File::create(&path).ok()
    });

    tracing_subscriber::registry()
        .with(tracing_subscriber::fmt::layer().with_filter(filter()))
        .with(file.map(|file| {
            tracing_subscriber::fmt::layer()
                .with_ansi(false)
                .with_writer(std::sync::Mutex::new(file))
                .with_filter(filter())
        }))
        .init();
    if let Some(path) = settings::log_path() {
        tracing::info!("logging to {}", path.display());
    }
}

/// Shifts `vdr.log` to `vdr.1.log`, `vdr.1.log` to `vdr.2.log`, and so on,
/// dropping the oldest. Renames only, so a run with no log folder loses
/// nothing but the file.
fn rotate(path: &std::path::Path) {
    let numbered = |n: u32| path.with_file_name(format!("vdr.{n}.log"));
    // Before the numbering, the one kept run was `vdr.prev.log`. Carried over
    // once as the last run, so an upgrade does not lose it.
    let prev = path.with_file_name("vdr.prev.log");
    if prev.exists() && !numbered(1).exists() {
        let _ = std::fs::rename(&prev, numbered(1));
    }
    for n in (1..KEPT_LOGS).rev() {
        let _ = std::fs::rename(numbered(n), numbered(n + 1));
    }
    let _ = std::fs::rename(path, numbered(1));
}

/// Picks rustls's crypto backend for the whole process, once, before anything
/// builds a TLS client.
///
/// **Without it, joining a room at an `http://` relay panics.** That form fetches
/// the relay's certificate hash over plain HTTP with `reqwest`, which builds
/// its client on rustls's *process* default -- and there is none, because both
/// `aws-lc-rs` and `ring` are compiled into the tree, so rustls refuses to
/// guess. The panic is inside moq-native's (now moq-tokio's) reconnect task, so all that reached
/// the call was "reconnect stopped". moq-native's own TLS passes a provider
/// explicitly, which is why direct calls never hit this.
///
/// aws-lc-rs, to match the backend moq-native is built with.
fn install_crypto_provider() {
    if rustls::crypto::aws_lc_rs::default_provider()
        .install_default()
        .is_err()
    {
        // Only possible if something installed one first, which is fine.
        tracing::debug!("a rustls crypto provider was already installed");
    }
}

/// Complains if the app was built without dx, which leaves it unstyled.
///
/// `asset!` compiles to a placeholder only dx substitutes, and nothing
/// downstream treats the leftover as an error -- the resolver answers it with a
/// 404 whose *body* Blitz then parses as a stylesheet. Enabling dioxus-native's
/// `tracing` does not catch this; see README.
fn warn_if_unbundled() {
    if TAILWIND_CSS.to_string().contains("replaced by dx") {
        tracing::error!(
            "stylesheet was not bundled -- the window will be unstyled. \
             Build with `dx build --renderer native` or `dx serve --renderer native`."
        );
    }
}

#[component]
fn App() -> Element {
    camera::use_devices_provider();
    audio::use_microphones_provider();
    audio::use_outputs_provider();

    rsx! {
        document::Title { "Vdr "}
        document::Stylesheet { href: TAILWIND_CSS }
        // The page's root element, with the keyboard shortcuts on it, is the
        // call screen's own: that is where the call's controls are.
        components::CallScreen {}
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_last_three_runs_are_kept() {
        let dir = std::env::temp_dir().join(format!("vdr-rotate-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("vdr.log");
        let read = |name: &str| std::fs::read_to_string(dir.join(name)).ok();
        for run in 1..=5 {
            rotate(&path);
            std::fs::write(&path, run.to_string()).unwrap();
        }
        assert_eq!(read("vdr.log").as_deref(), Some("5"));
        assert_eq!(read("vdr.1.log").as_deref(), Some("4"));
        assert_eq!(read("vdr.2.log").as_deref(), Some("3"));
        assert_eq!(read("vdr.3.log").as_deref(), Some("2"));
        assert_eq!(read("vdr.4.log"), None);
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn the_old_single_copy_becomes_the_last_run() {
        let dir = std::env::temp_dir().join(format!("vdr-rotate-prev-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("vdr.log");
        std::fs::write(dir.join("vdr.prev.log"), "old").unwrap();
        std::fs::write(&path, "last").unwrap();
        rotate(&path);
        assert_eq!(std::fs::read_to_string(dir.join("vdr.1.log")).unwrap(), "last");
        assert_eq!(std::fs::read_to_string(dir.join("vdr.2.log")).unwrap(), "old");
        assert!(!dir.join("vdr.prev.log").exists());
        std::fs::remove_dir_all(&dir).unwrap();
    }
}
